/**
 * Render an inline SVG for a named icon.
 *
 * An unknown name used to fall back to an empty path: valid markup, no drawing,
 * no error -- a button that only reveals itself when the pointer happens to land
 * on it. Say so loudly instead; the caller has a name to fix.
 */
export function icon(name, cls = '') {
  const d = ICONS[name];
  if (!d) {
    console.error(`icon: 没有名为 "${name}" 的图标`);
  }
  return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${d || ''}"/></svg>`;
}

/**
 * The app brand mark: the whole icon, not just the letter.
 *
 * This markup is generated by tools/genicon.py's brand_svg() from the same geometry as
 * the raster icon, so the rail mark and the installed .ico are one picture — tile, rim,
 * F, and the film-perforation hint. It used to be the bare F, which is why the in-app
 * icon and the exe icon looked like two different apps.
 *
 * Colours live in CSS (.brand-tile / .brand-rim / .brand-f / .brand-hint) so the mark
 * can pick up the theme instead of being hard-coded to the raster's values.
 */
export function brandSvg() {
  return `<svg viewBox="0 0 24 24" aria-hidden="true"><rect class="brand-tile" x="0" y="0" width="24" height="24" rx="5.64"/><rect class="brand-rim" x="0.5" y="0.5" width="23" height="23" rx="5.64" fill="none"/><rect class="brand-hint" x="2.69" y="6.26" width="1.2" height="1.97" rx="0.54"/><rect class="brand-hint" x="2.69" y="9.43" width="1.2" height="1.97" rx="0.54"/><rect class="brand-hint" x="2.69" y="12.6" width="1.2" height="1.97" rx="0.54"/><rect class="brand-hint" x="2.69" y="15.77" width="1.2" height="1.97" rx="0.54"/><path class="brand-f" d="M8.57 4.32 L12.09 4.32 L12.09 19.68 L8.57 19.68ZM8.57 4.32 L17.59 4.32 L17.59 7.15 L8.57 7.15ZM8.57 11 L13.62 11 L13.62 13.83 L8.57 13.83ZM13.62 11 L16.68 12.42 L13.62 13.83Z"/></svg>`;
}
